        return "Failed"

    mapping = {}
    for e, o in zip(encoded, original):
        if e in mapping:
            if mapping[e] != o:
                return "Failed"
        else:
            mapping[e] = o

    # Ensure all 26 letters are present in the mapping (bijective mapping)
    if len(mapping) != 26:
        return "Failed"
